CREATE TABLE IF NOT EXISTS app_sessions (hash TEXT PRIMARY KEY, username TEXT NOT NULL REFERENCES users(name) ON UPDATE CASCADE ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS app_sessions_expiry ON app_sessions(expires);
CREATE TABLE IF NOT EXISTS app_meta (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 0, mutation TEXT NOT NULL DEFAULT '', updated_at TEXT);
INSERT OR IGNORE INTO app_meta(id) VALUES(1);
CREATE TABLE IF NOT EXISTS app_records (key TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_mutations (id TEXT PRIMARY KEY, revision INTEGER NOT NULL, digest TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_history (revision INTEGER NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL, actor TEXT NOT NULL, saved_at TEXT NOT NULL, PRIMARY KEY(revision,key));
CREATE TABLE IF NOT EXISTS app_files (key TEXT PRIMARY KEY, digest TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS app_file_chunks (key TEXT NOT NULL REFERENCES app_files(key), n INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(key,n));
